bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test -d "$root/.git" || exit 60
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 61
python3 - "$root" <<'PY'
import ast,pathlib,sys
root=pathlib.Path(sys.argv[1])
p=root/"scripts/userbot_test_client.py"
src=p.read_text(encoding="utf-8")
tree=ast.parse(src)
tokens={"link_rich_flow_smoke","link_photo_caption_smoke"}
found={t:(t in src) for t in tokens}
if not found["link_rich_flow_smoke"]:raise SystemExit(80)
if found["link_photo_caption_smoke"]:raise SystemExit(81)
ifexps=[n for n in ast.walk(tree) if isinstance(n,ast.IfExp) and "link_rich_flow_smoke" in (ast.get_source_segment(src,n.test) or "")]
if len(ifexps)==1:
 n=ifexps[0]
 test=n.test
 if isinstance(test,ast.Compare) and isinstance(test.comparators[0],ast.Set):raise SystemExit(82)
 raise SystemExit(83)
if len(ifexps)>1:raise SystemExit(84)
if any(isinstance(n,ast.If) and "link_rich_flow_smoke" in (ast.get_source_segment(src,n.test) or "") for n in ast.walk(tree)):raise SystemExit(85)
raise SystemExit(86)
PY
